tool_input.newString:
const readDesignActiveTool = async () => {
  return await page.evaluate(() => {
    // activeTool lives in the xstate machine context (designApps[key].activeTool),
    // not in the designApp store instance snapshot.
    const actor = (window as any).__SEMIO_ACTOR__;
    if (!actor) { console.log("[DEBUG] readDesignActiveTool: no actor"); return null; }
    const snapshot = actor.getSnapshot();
    if (!snapshot?.context) { console.log("[DEBUG] readDesignActiveTool: no snapshot.context"); return null; }
    const designApps = snapshot.context.designApps;
    if (!designApps) { console.log("[DEBUG] readDesignActiveTool: no designApps"); return null; }
    const url = window.location.pathname;
    const kitGuidMatch = url.match(/\/kits\/([^/]+)/);
    const designGuidMatch = url.match(/\/designs\/([^/]+)/);
    const kitGuid = kitGuidMatch?.[1];
    const designGuid = designGuidMatch?.[1];
    if (!kitGuid || !designGuid) { console.log("[DEBUG] readDesignActiveTool: no kitGuid or designGuid from URL:", url); return null; }
    const key = `${kitGuid}:${designGuid}`;
    const allKeys = Object.keys(designApps);
    console.log("[DEBUG] readDesignActiveTool: designApps keys:", JSON.stringify(allKeys), "looking for key:", key);
    const designApp = designApps[key];
    if (!designApp) {
      console.log("[DEBUG] readDesignActiveTool: no designApp for key", key);
      // Try finding any matching key
      for (const k of allKeys) {
        console.log("[DEBUG] readDesignActiveTool: checking key", k, "app:", JSON.stringify(Object.keys((designApps as any)[k] || {})));
      }
      return null;
    }
    console.log("[DEBUG] readDesignActiveTool: found designApp, activeTool:", designApp.activeTool);
    return designApp?.activeTool ?? null;
  });
};

