// Helper to check toggle pressed state via DOM inspection in browser context
const isTogglePressed = async (toggleId: string) => {
  return page.evaluate((id) => {
    const el = document.getElementById(id);
    if (!el) return false;
    // Check root data-state first (ToggleGroup root)
    if (el.getAttribute("data-state") === "on") return true;
    // Check child ToggleGroupItem data-state
    const item = el.querySelector('[data-slot="toggle-group-item"]');
    if (item && item.getAttribute("data-state") === "on") return true;
    // Check aria-pressed on root or child
    if (el.getAttribute("aria-pressed") === "true") return true;
    if (item && item.getAttribute("aria-pressed") === "true") return true;
    return false;
  }, toggleId);
};

