const readDesignActiveTool = async () => {
  const result = await page.evaluate(() => {
    // Read activeTool from the DesignStore instance (store.designApps Map),
    // which is the ground truth after store.execute("semio.designApp.setActiveTool").
    const store = (window as any).__SEMIO_STORE__;
    if (!store) return { tool: null as string | null, debug: "no-store" };
    const url = window.location.pathname;
    const kitGuid = url.match(/\/kits\/([^/]+)/)?.[1];
    const designGuid = url.match(/\/designs\/([^/]+)/)?.[1];
    if (!kitGuid || !designGuid) return { tool: null as string | null, debug: "no-guids, url:" + url };
    const designAppsMap = (store as any).designApps as Map<string, Map<string, any>> | undefined;
    if (!designAppsMap) return { tool: null as string | null, debug: "no-designApps-map" };
    const kitMap = designAppsMap.get(kitGuid);
    if (!kitMap) return { tool: null as string | null, debug: `no-kitMap, kitGuid:${kitGuid}, mapKeys:[${Array.from(designAppsMap.keys()).join(",")}]` };
    const designApp = kitMap.get(designGuid);
    if (!designApp) return { tool: null as string | null, debug: `no-designApp, designGuid:${designGuid}, kitMapKeys:[${Array.from(kitMap.keys()).join(",")}]` };
    const snap = typeof designApp.snapshot === "function" ? designApp.snapshot() : null;
    if (!snap) return { tool: null as string | null, debug: "no-snapshot" };
    return { tool: (snap.activeTool ?? null) as string | null, debug: "ok" };
  });
  if (result.debug !== "ok") console.log(`[Design] readDesignActiveTool debug: ${result.debug}`);
  return result.tool;
};

