// Debug helper: dump all attributes of toggle element and its children
const debugToggle = async (toggleId: string): Promise<string> => {
  return page.evaluate((id) => {
    const el = document.getElementById(id);
    if (!el) return `[DEBUG] No element found with id: ${id}`;
    const getAttrs = (e: Element) => {
      const a: Record<string, string> = {};
      for (const attr of e.attributes) a[attr.name] = attr.value;
      return a;
    };
    const rootAttrs = getAttrs(el);
    const items = el.querySelectorAll("*");
    const childInfo: { tag: string; attrs: Record<string, string> }[] = [];
    items.forEach((item) => childInfo.push({ tag: item.tagName, attrs: getAttrs(item) }));
    return JSON.stringify({ rootTag: el.tagName, rootAttrs, children: childInfo.slice(0, 5) });
  }, toggleId);
};

// Helper to check toggle pressed state via DOM inspection in browser context
const isTogglePressed = async (toggleId: string) => {
  return page.evaluate((id) => {
    const el = document.getElementById(id);
    if (!el) return false;
    // Check root data-state first (ToggleGroup root)
    if (el.getAttribute("data-state") === "on") return true;
    // Check child ToggleGroupItem data-state
    const item = el.querySelector('[data-slot="toggle-group-item"]');
    if (item && item.getAttribute("data-state") === "on") return true;
    // Check aria-pressed on root or child
    if (el.getAttribute("aria-pressed") === "true") return true;
    if (item && item.getAttribute("aria-pressed") === "true") return true;
    return false;
  }, toggleId);
};

